mapper.select:
SELECT *
FROM t_material tm
where tm.is_delete =0
    and experiment_plan_id = #{dto.experimentPlanId}

        and tm.material_type = #{dto.materialType}


        AND tm.material_attribution = #{userName}

SELECT tm.*, ep.experiment_name as experiment_plan_name, ep.experiment_title as experiment_plan_title FROM t_material tm left join t_experiment_plan ep on tm.experiment_plan_id = ep.id and ep.is_deleted = 0 where tm.is_delete =0
and tm.material_type = #{dto.materialType}
and tm.material_name like concat('%' ,#{dto.materialName} ,'%')
and tm.tag like concat('%' ,#{dto.tag} ,'%')
and tm.material_status = #{dto.materialStatus}
and (tm.material_status = #{dto.materialStatus} or (#{roleId} = 1 and tm.material_status = #{dto.materialStatus}))
and tm.material_status = 'OPEN'
and tm.material_attribution = #{userName}
ORDER BY tm.update_date DESC

SELECT * FROM t_material tm where tm.is_delete =0
and tm.material_name like concat('%' ,#{dto.materialName} ,'%')
and tm.material_type = #{dto.materialType}
and tm.material_status = #{dto.materialStatus}
and (tm.material_status = 'WAIT_REVIEW' or tm.material_status = 'OPEN')
and tm.material_status = 'OPEN'

SELECT * FROM t_material tm where tm.is_delete = 0 and tm.material_status = 'OPEN'
and tm.material_attribution = #{dto.materialAttribution}
and tm.material_type = #{dto.materialType}
and tm.material_name like concat('%', #{dto.materialName}, '%')
ORDER BY tm.update_date DESC

select tm.*, ep.experiment_name as experiment_plan_name, ep.experiment_title as experiment_plan_title, case when f.id is not null then 1 else 0 end as is_favorite from t_material tm left join t_experiment_plan ep on tm.experiment_plan_id = ep.id and ep.is_deleted = 0 left join t_favorite f on tm.id = f.target_id and f.favorite_type = 'MATERIAL' and f.user_id = #{userId} and f.is_deleted = 0 where tm.is_delete = 0 and tm.material_status = 'OPEN'
and tm.material_attribution = #{dto.materialAttribution}
and tm.material_type = #{dto.materialType}
and tm.material_name like concat('%', #{dto.materialName}, '%')
ORDER BY tm.update_date DESC
